bicep:
// ---------------------------------------------------------------------------
// main.bicep — generated by azx (App Intent Service · POC #1, dry-run engine)
// DRY-RUN PREVIEW ONLY — review before deploying. azx made no Azure calls.
// Resolved region: eastus2
// Estimated cost: ~$170/mo USD
// ---------------------------------------------------------------------------

targetScope = 'resourceGroup'

@description('Azure region for all resources.')
param location string = 'eastus2'

// Consumption plan — you pay only for running container replicas.
resource appEnv 'Microsoft.App/managedEnvironments@2024-03-01' = {
  name: 'cae-django-notes'
  location: location
  properties: {}
}

// Fallback options considered: Azure App Service (always-on web apps) or Azure Static Web Apps (static/JAMstack).
resource web 'Microsoft.App/containerApps@2024-03-01' = {
  name: 'ca-django-notes'
  location: location
  properties: {
    managedEnvironmentId: appEnv.id
    configuration: {
      ingress: {
        external: true
        targetPort: 3000
      }
    }
    template: {
      scale: {
        minReplicas: 1
        maxReplicas: 10
      }
    }
  }
  dependsOn: [
    appEnv
    postgres
  ]
}

// GeneralPurpose tier.
resource postgres 'Microsoft.DBforPostgreSQL/flexibleServers@2024-08-01' = {
  name: 'psql-django-notes'
  location: location
  sku: {
    name: 'Standard_D2s_v3'
    tier: 'GeneralPurpose'
  }
  properties: {
      version: '16'
      storage: {
        storageSizeGB: 32
      }
      authConfig: {
        passwordAuth: 'Enabled'
      }
  }
}

resource postgresDb 'Microsoft.DBforPostgreSQL/flexibleServers/databases@2024-08-01' = {
  name: 'psql-django-notes/appdb'
  properties: {
    charset: 'UTF8'
    collation: 'en_US.utf8'
  }
  dependsOn: [
    postgres
  ]
}

output webAppName string = web.name
output postgresServerName string = postgres.name
